(p, sb) = map(int, input().split())
ans = list()
for i in range(p):
	(s, n) = (list(map(int, input().split())), list(map(int, input().split())))
	lis = list()
	cnt = 0
	for j in range(sb):
		lis.append([s[j], n[j]])
	lis.sort()
	for j in range(sb - 1):
		if lis[j][1] > lis[j + 1][1]:
			cnt += 1
	ans.append([cnt, i])
ans.sort()
for i in ans:
	print(i[1] + 1)
